// Optimistic transition: the caller names the statuses it is willing to move away from,
// so two concurrent apply commands cannot both start the job.
func (q *Queries) SetImportBatchStatus(ctx context.Context, arg SetImportBatchStatusParams) (int64, error) {
	result, err := q.db.Exec(ctx, setImportBatchStatus,
		arg.Status,
		arg.ErrorSummary,
		arg.TenantID,
		arg.ID,
		arg.FromStatuses,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

